<?php
function list_users($pdo){require_admin($pdo);$rows=$pdo->query('SELECT id,name,email,phone_number,created_at FROM users ORDER BY id DESC')->fetchAll();$out=array();foreach($rows as$u)$out[]=array('id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'phone_number'=>$u['phone_number'],'created_at'=>iso_date($u['created_at']));json_response($out);}
function create_brand($pdo){require_admin($pdo);$i=json_body();require_fields($i,array('name'));$name=trim($i['name']);$pdo->prepare('INSERT INTO brands(name) VALUES(?)')->execute(array($name));json_response(array('id'=>(int)$pdo->lastInsertId(),'name'=>$name),201);}
function delete_brand($pdo,$id){require_admin($pdo);$s=$pdo->prepare('DELETE FROM brands WHERE id=?');$s->execute(array($id));if(!$s->rowCount())error_response('Бренд не знайдено.',404);json_response(null,204);}
function create_product($pdo){require_admin($pdo);$d=product_input(json_body(),true);$cols=array_keys($d);$pdo->prepare('INSERT INTO products('.implode(',',$cols).') VALUES('.implode(',',array_fill(0,count($cols),'?')).')')->execute(array_values($d));json_response(find_product($pdo,$pdo->lastInsertId()),201);}
function update_product($pdo,$id){require_admin($pdo);find_product($pdo,$id);$d=product_input(json_body(),false);if(!$d)error_response('Немає даних для оновлення.',422);$sets=array();foreach(array_keys($d)as$f)$sets[]=$f.'=?';$values=array_values($d);$values[]=$id;$pdo->prepare('UPDATE products SET '.implode(',',$sets).' WHERE id=?')->execute($values);json_response(find_product($pdo,$id));}
function delete_product($pdo,$id){require_admin($pdo);$p=find_product($pdo,$id);$pdo->prepare('DELETE FROM products WHERE id=?')->execute(array($id));foreach($p['images']as$image){$f=dirname(dirname(__DIR__)).'/public'.$image['image_url'];if(is_file($f))unlink($f);}json_response(null,204);}
function upload_product_image($pdo,$id){require_admin($pdo);find_product($pdo,$id);if(!isset($_FILES['image'])||$_FILES['image']['error']!==UPLOAD_ERR_OK)error_response('Завантажте зображення.',422);$file=$_FILES['image'];$types=array('image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!isset($types[$mime])||$file['size']>5242880)error_response('Дозволені JPG, PNG, WEBP до 5 МБ.',422);$dir=dirname(dirname(__DIR__)).'/public/uploads/products';if(!is_dir($dir)&&!mkdir($dir,0775,true))error_response('Не вдалося створити каталог.',500);$name=uniqid('',true).'.'.$types[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))error_response('Не вдалося зберегти зображення.',500);$main=filter_var(isset($_POST['is_main'])?$_POST['is_main']:false,FILTER_VALIDATE_BOOLEAN);if($main)$pdo->prepare('UPDATE product_images SET is_main=0 WHERE product_id=?')->execute(array($id));$url='/uploads/products/'.$name;$pdo->prepare('INSERT INTO product_images(product_id,image_url,is_main) VALUES(?,?,?)')->execute(array($id,$url,$main));json_response(array('id'=>(int)$pdo->lastInsertId(),'product_id'=>(int)$id,'image_url'=>$url,'is_main'=>$main),201);}
function delete_product_image($pdo,$pid,$id){require_admin($pdo);$s=$pdo->prepare('SELECT image_url FROM product_images WHERE id=? AND product_id=?');$s->execute(array($id,$pid));$i=$s->fetch();if(!$i)error_response('Зображення не знайдено.',404);$pdo->prepare('DELETE FROM product_images WHERE id=?')->execute(array($id));$f=dirname(dirname(__DIR__)).'/public'.$i['image_url'];if(is_file($f))unlink($f);json_response(null,204);}
function update_order_status($pdo,$id){require_admin($pdo);$i=json_body();$allowed=array('Нове','В обробці','Відправлено','Виконано','Скасовано');if(!isset($i['status'])||!in_array($i['status'],$allowed,true))error_response('Некоректний статус.',422);find_order($pdo,$id);$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute(array($i['status'],$id));json_response(order_response($pdo,find_order($pdo,$id)));}
function update_order_contacts($pdo,$id){require_admin($pdo);$i=json_body();$sets=array();$v=array();foreach(array('customer_name','phone','email','comment')as$f)if(array_key_exists($f,$i)){$sets[]=$f.'=?';$v[]=$i[$f];}if(!$sets)error_response('Немає даних для оновлення.',422);if(isset($i['email']))require_valid_email($i['email']);find_order($pdo,$id);$v[]=$id;$pdo->prepare('UPDATE orders SET '.implode(',',$sets).' WHERE id=?')->execute($v);json_response(order_response($pdo,find_order($pdo,$id)));}
function delete_order($pdo,$id){require_admin($pdo);find_order($pdo,$id);$pdo->prepare('DELETE FROM orders WHERE id=?')->execute(array($id));json_response(null,204);}
function update_application_status($pdo,$id){require_admin($pdo);$i=json_body();if(!isset($i['status'])||!in_array($i['status'],array('Нове','Опрацьовано'),true))error_response('Некоректний статус.',422);application_by_id($pdo,$id);$pdo->prepare('UPDATE applications SET status=? WHERE id=?')->execute(array($i['status'],$id));json_response(application_by_id($pdo,$id));}
function delete_application($pdo,$id){require_admin($pdo);application_by_id($pdo,$id);$pdo->prepare('DELETE FROM applications WHERE id=?')->execute(array($id));json_response(null,204);}
